{
  "name": "网络摄像机",
  "name_en": "IP Camera",
  "manufacturer": "",
  "description": "网络摄像机是一种通过以太网或局域网输出视频流的成像设备，可用于实验过程远程观察、样品与装置状态监控、图像记录以及实时帧采集。",
  "description_en": "An IP camera is an imaging device that streams video over Ethernet or a local network. In laboratories it is used for remote observation of experiments, monitoring samples and instruments, recording visual status, and acquiring live image frames.",
  "tag_hints": [
    "IP camera",
    "network video streaming",
    "remote experiment monitoring",
    "live frame capture",
    "machine vision",
    "laboratory imaging"
  ],
  "actions": [
    {
      "action_name": "auto-start_async",
      "description": "开始后台连续采集网络摄像机视频帧。",
      "description_en": "Start background continuous capture of video frames from the IP camera."
    },
    {
      "action_name": "auto-stop",
      "description": "停止网络摄像机的后台视频帧采集。",
      "description_en": "Stop background video frame capture from the IP camera."
    },
    {
      "action_name": "auto-get_latest_frame",
      "description": "获取网络摄像机最近采集到的一帧图像。",
      "description_en": "Get the most recently captured image frame from the IP camera."
    },
    {
      "action_name": "auto-set_exposure",
      "description": "设置曝光时间或曝光等级。",
      "description_en": "Set the exposure time or exposure level."
    },
    {
      "action_name": "auto-get_exposure",
      "description": "获取曝光时间或曝光等级。",
      "description_en": "Get the exposure time or exposure level."
    },
    {
      "action_name": "auto-set_gain",
      "description": "设置图像增益。",
      "description_en": "Set the image gain."
    },
    {
      "action_name": "auto-get_gain",
      "description": "获取图像增益。",
      "description_en": "Get the image gain."
    },
    {
      "action_name": "auto-enable_auto_exposure",
      "description": "启用或禁用自动曝光。",
      "description_en": "Enable or disable auto exposure."
    },
    {
      "action_name": "auto-set_frame_size",
      "description": "设置视频帧分辨率。",
      "description_en": "Set the video frame size or resolution."
    },
    {
      "action_name": "auto-discover",
      "description": "查询可发现的网络摄像机；此类设备通常需要手动配置连接信息。",
      "description_en": "Query discoverable IP cameras; these devices typically require manual connection configuration."
    },
    {
      "action_name": "auto-get_config_schema",
      "description": "获取连接网络摄像机所需配置项的定义。",
      "description_en": "Get the definition of configuration fields required to connect to the IP camera."
    }
  ]
}

